  TOKEN=$(printf "%s" "$HTML" | sed -n 's/.*name="authenticity_token" value="\([^"]\+\)".*/\1/p' | head -n1); 
  curl -s -b "$C" -c "$C" -A "$UA" -X POST "$BASE/users/sign_in" -H 'Content-Type: application/x-www-form-urlencoded' \
    --data-urlencode "authenticity_token=$TOKEN" \
    --data-urlencode "user[login]=root" \
    --data-urlencode "user[password]=theagentcompany" \
    --data-urlencode "user[remember_me]=0" >/dev/null; 
fi; 
# Fetch projects and build audit report
curl -s -b "$C" -A "$UA" "$BASE/api/v4/projects?per_page=100" > /tmp/projects.json; 
ids=$(jq -r '.[].id' /tmp/projects.json); 
{
  echo '['; first=1; 
  for id in $ids; do 
    proj=$(jq -c ".[] | select(.id==$id) | {id, path_with_namespace}" /tmp/projects.json); 
    members=$(curl -s -b "$C" -A "$UA" "$BASE/api/v4/projects/$id/members/all?per_page=100" | jq -c '[.[] | {id,username,access_level}]'); 
    if [ $first -eq 0 ]; then echo ','; fi; 
    printf '{"project":%s,"members":%s}' "$proj" "$members"; 
    first=0; 
  done; 
  echo ']'; 
} > /outputs/gitlab_member_audit.json; 
cat /outputs/gitlab_member_audit.json | sed -n '1,120p'

